let market=null,sessionId=null,selected=0,side='buy',tab='portfolio',timer=null,won=false,traderSelected=0,rankingMode='equity',rankingPage=0,auto=false,localBusy=false,compiling=false,historyRequest=0,chartBars=[],chartHover=-1,chartOffset=0;let creating=false;let rankingData=null,rankingRequest=0,peoplePage=0,peopleData=null,peopleRequest=0;
const $=id=>document.getElementById(id),money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(v),num=v=>new Intl.NumberFormat('en-US').format(v),pct=v=>`${v>=0?'+':''}${v.toFixed(2)}%`,signed=v=>`${v>=0?'+':'−'}${money(Math.abs(v))}`;
