function feedback(message,error=false){$('feedback').textContent=message;$('feedback').classList.toggle('error',error);}
function financeFeedback(r){$('financeFeedback').textContent=r.message;$('financeFeedback').classList.toggle('error',!r.ok);render();}
function renderFinancing(){
 const m=market.margin(),rank=market.ranking().find(a=>a.id===market.playerId).rank;
 if(document.activeElement!==$('leverage'))$('leverage').value=m.limit;$('debt').textContent=money(m.debt);$('borrowCapacity').textContent=money(Math.floor(m.capacity*100)/100);$('loanInterest').textContent=money(m.interest);$('marginRatio').textContent=`${(m.ratio*100).toFixed(2)}%`;$('playerRank').textContent=`#${rank} / ${market.count+1}`;
 $("marginThreshold").textContent=`保证金比例 · 强平线 ${(m.maintenance*100).toFixed(2)}%`;
 const warning=m.liquidating||m.ratio<m.maintenance*1.28;const status=$('riskStatus');status.textContent=m.liquidating?'强平中 · 只可减仓/平空':m.liabilities<=.000001?'无负债':warning?'接近强平线':'融资正常';status.className=warning?'risk-danger':'risk-safe';$('marginRatio').className=warning?'down':'up';
 $('borrow').disabled=m.liquidating||m.capacity<.01;$('borrowMax').disabled=$('borrow').disabled;$('repay').disabled=m.debt<=.000001;$('repayAll').disabled=$('repay').disabled;
 $('financeInfo').textContent=`实际资产杠杆 ${Number.isFinite(m.leverage)?m.leverage.toFixed(2)+'×':'净资产不足'} · 利率 ${(market.loanRate*100).toFixed(4)}% / 刻，利息按正负调整负债 · 空头市值 ${money(m.shortValue)} · 借股费 ${(market.stockBorrowRate*100).toFixed(3)}% / 刻 · 强平线 ${(m.maintenance*100).toFixed(2)}% / 恢复线 ${(m.recovery*100).toFixed(2)}% · 累计融资成本 ${money(market.player.financeCosts)}${m.liquidating?` · ${(m.maintenance*100).toFixed(2)}% 触发，恢复 ${(m.recovery*100).toFixed(2)}% 后停止；无买方时下刻重试`:''}`;
}
function setSide(value){side=value;for(const [id,v]of [['buy','buy'],['sell','sell'],['shortSell','short'],['coverShort','cover']]){$(id).classList.toggle('active',side===v);$(id).classList.toggle('sell-active',side===v&&['sell','short'].includes(v));}$('submit').classList.toggle('sell-button',['sell','short'].includes(side));renderTicket();}
function choose(i){selected=i;chartOffset=0;chartBars=[];$('limitPrice').value=market.stocks[i].price;feedback('');render();void loadChart();}
function spark(s,limit=35){const h=s.history.slice(-limit),min=Math.min(...h)*.999,max=Math.max(...h)*1.001,points=h.map((p,i)=>`${h.length===1?0:i/(h.length-1)*65},${25-(p-min)/(max-min)*22}`).join(' ');return `<svg viewBox="0 0 65 28" aria-hidden="true"><polyline points="${h.length===1?'0,14 65,14':points}" fill="none" stroke="${s.color}" stroke-width="1.5"/></svg>`;}
function renderStocks(){
  $('stocks').innerHTML=market.stocks.map((s,i)=>{const change=(s.price/s.previous-1)*100;return `<button class="stock-card ${i===selected?'selected':''}" data-stock="${i}" style="--stock-color:${s.color}" aria-pressed="${i===selected}"><div class="stock-top"><span class="stock-symbol">${s.symbol}</span><span class="stock-sector">${s.sector}</span>${spark(s)}</div><div class="stock-bottom"><strong>${money(s.price)}</strong><small title="较上一周期收盘 ${money(s.previous)}；开局累计 ${pct((s.price/s.start-1)*100)}" class="${change>=0?'up':'down'}">${pct(change)}<span class="period-label"> / 刻</span></small></div><div class="stock-supply">发行 ${num(s.supply)} 股</div></button>`;}).join('');
  $('stocks').querySelectorAll('[data-stock]').forEach(b=>b.onclick=()=>choose(Number(b.dataset.stock)));
}
function levels(orders){const m=new Map();orders.forEach(o=>m.set(o.price,(m.get(o.price)||0)+o.qty));return [...m.entries()].slice(0,5);}
function renderBook(){const book=market.book(selected),buys=market.bookLevels?market.bookLevels[selected].buy.map(l=>[l.price,l.qty]):levels(book.buy),sells=market.bookLevels?market.bookLevels[selected].sell.map(l=>[l.price,l.qty]):levels(book.sell),max=Math.max(1,...[...buys,...sells].map(a=>a[1]));$('book').innerHTML=Array.from({length:5},(_,i)=>`<div class="book-row">${[buys[i],sells[i]].map((l,j)=>`<div class="book-cell ${j?'ask down':'up'}" style="--depth:${l?l[1]/max*100:0}%"><span>${l?money(l[0]):'—'}</span><span>${l?num(l[1]):'—'}</span></div>`).join('')}</div>`).join('');}
function quote(qty){const type=$('orderType').value;if(type==='limit')return {amount:qty*Number($('limitPrice').value),filled:qty};const book=market.book(selected);let left=qty,amount=0;for(const o of ['buy','cover'].includes(side)?book.sell:book.buy){if(o.owner===market.playerId)continue;const q=Math.min(left,o.qty);amount+=q*o.price;left-=q;if(left<=0)break;}return {amount,filled:qty-left};}
function renderTicket(){const s=market.stocks[selected],qty=Number($('quantity').value),valid=Number.isSafeInteger(qty)&&qty>0,q=valid?quote(qty):{amount:0,filled:0},names={buy:'买入',sell:'卖出',short:'借股做空',cover:'买回平空'};$('ticketSymbol').textContent=s.symbol;$('submit').textContent=`${names[side]} ${s.symbol} →`;$('estimate').textContent=valid&&Number.isFinite(q.amount)?money(q.amount):'—';$('ticketAvailable').textContent=side==='short'?`可借 ${num(market.lendingAvailable[selected])} 股 · 空头额度 ${money(market.margin().capacity)}`:side==='cover'?`待平 ${num(market.player.shorts[selected])} 股 · 可用 ${money(market.availableCash(market.playerId))}`:side==='buy'?`可用 ${money(market.availableCash(market.playerId))}`:`可卖 ${market.availableShares(market.playerId,selected)} 股 · 持有 ${market.player.shares[selected]} 股`;$('ticketNote').textContent=['short','cover'].includes(side)?`立即成交，剩余取消；做空需至少 2× 上限，借股费 ${(market.stockBorrowRate*100).toFixed(3)}% / 刻，空头补偿分红。`:$('orderType').value==='limit'?'限价挂单冻结资金 / 股数，30 刻有效。':valid&&q.filled<qty?`对手盘可成交 ${q.filled} 股，剩余自动取消。`:'估价参考近端盘口，大单以服务器实际成交为准。';$('submit').disabled=!valid;}
function renderMarketOverview(){const o=market.marketOverview;if(!o){$('marketIndex').textContent='—';$('marketIndexBasis').textContent='请重启服务以加载大盘统计';return;}const ix=o.index,t=o.totals;$('marketIndex').textContent=ix.value.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});$('marketIndexChange').textContent=`${pct(ix.changePct)} / 刻 · 开局 ${pct(ix.fromStartPct)}`;$('marketIndexChange').className=ix.changePct>=0?'up':'down';$('marketIndexBasis').textContent=`五股发行量加权 · 价格指数${ix.complete?'':' · 本刻未封存'}`;$('marketIndexTrend').innerHTML=spark({history:o.indexHistory.map(r=>r.value),color:ix.changePct>=0?'#b6ed76':'#f08080'},120);$('marketTotals').innerHTML=[['全市场现金',t.totalCash,'含冻结现金 · 玩家与所有 NPC'],['全体总负债',t.totalLiabilities,'美元贷款 + 借股归还义务'],['全体融资债务',t.totalDebt,'美元贷款本金及计入的利息'],['全市场股票市值',ix.marketCap,'发行股数 × 最新成交价'],['借股归还义务',t.totalShortLiability,'按现价计值 · 不计入美元贷款']].map(([name,value,note])=>`<div><small>${name}</small><strong>${money(value)}</strong><span>${note}</span></div>`).join('');const spread=market.cashRate-market.loanRate;$('marketRateNote').textContent=`现金利率 ${(market.cashRate*100).toFixed(3)}% / 刻 · 债务利率 ${(market.loanRate*100).toFixed(3)}% / 刻 · ${spread>0?'借款持币有正利差；仍占用杠杆额度':spread<0?'闲置资金还债优于保留借款':'借款持币利差为零'}。${market.cashRate<0?'现金会扣息，持币成本已纳入 NPC 决策。':''}`;}
function renderCompany(){const s=market.stocks[selected],c=s.company;$('economyStatus').textContent=`经济因子 ${market.economy.factor.toFixed(3)}× · 波动 ${(market.economy.volatility*100).toFixed(1)}% / 刻`;$('companyInfo').innerHTML=`<div><small>${s.symbol} 财报 / 第 ${c.reportTick} 刻</small><strong>${money(c.cashFlow)} / 刻</strong><span>经营现金流</span></div><div><small>公司现金 / 债务</small><strong>${money(c.cash)}</strong><span>债务 ${money(c.debt)}</span></div><div><small>营收 / 经营利润率</small><strong>${money(c.revenue)}</strong><span>${(c.operatingMargin*100).toFixed(2)}%</span></div><div><small>最近每股分红</small><strong>${"$"+c.dividendPerShare.toFixed(4)}</strong><span>${c.lastDividendTick?'第 '+c.lastDividendTick+' 刻支付':'尚未分红'} · 分红不保证</span></div><div><small>你的累计分红 / 借股成本</small><strong>${signed(market.player.totalDividends)}</strong><span>借股费 ${money(market.player.shortFees)}</span></div>`;}

function empty(title,body){return `<div class="empty"><div class="empty-icon">↗</div><strong>${title}</strong><small>${body}</small></div>`;}
function renderTable(){
 const p=market.player,area=$('tableArea'),entering=area.dataset.view!==tab;area.dataset.view=tab;if(entering)area.scrollTop=0;
 if(tab==='ranking'){
  const rows=rankingData?.rows||[],mine=rankingData?.mine||market.ranking(rankingMode)[0],size=25,pages=Math.ceil((market.count+1)/size);rankingPage=Math.max(0,Math.min(rankingPage,pages-1));
  const row=r=>`<tr class="${r.id===market.playerId?'player-row':''}"><td>${r.rank<=3?['🥇','🥈','🥉'][r.rank-1]:'#'+r.rank}</td><td>${r.name}${r.id===market.playerId?' · 玩家':''}<small>${r.id===market.playerId?'你的融资账户':MARKET_TYPES[r.type]}</small></td><td>${money(r.equity)}</td><td class="${(rankingMode==='trading'?r.tradingReturnPct:r.returnPct)>=0?'up':'down'}">${pct(rankingMode==='trading'?r.tradingReturnPct:r.returnPct)}</td><td>${money(r.debt)}</td></tr>`;
  // Keep controls alive across ticks: replacing the select closes its native popup.
  if(entering){area.innerHTML=`<div class="ranking-toolbar"><label>排序<select id="rankingMode" aria-label="排行排序"><option value="equity">净资产最高</option><option value="return">总收益率最高</option><option value="trading">投资收益率最高</option></select></label><span id="rankingPosition"></span><button id="myRank" class="quiet">定位自己</button></div><div class="people-note">净资产已扣负债 · 投资收益率剔除被动收入 · 数据实时更新</div><table><thead><tr><th>名次</th><th>交易者 / 策略</th><th>净资产</th><th>收益率</th><th>负债</th></tr></thead><tbody id="rankingRows"></tbody></table><div class="ranking-pages"><button class="quiet" id="rankPrevious">← 上一页</button><span id="rankingPagination"></span><button class="quiet" id="rankNext">下一页 →</button></div>`;
   $('rankingMode').value=rankingMode;$('rankingMode').onchange=()=>{rankingMode=$('rankingMode').value;rankingPage=0;rankingData=null;renderTable();void loadRanking();};$('myRank').onclick=()=>{const latest=market.ranking(rankingMode).find(r=>r.id===market.playerId);rankingPage=Math.floor((latest.rank-1)/size);renderTable();void loadRanking();};$('rankPrevious').onclick=()=>{rankingPage--;renderTable();void loadRanking();};$('rankNext').onclick=()=>{rankingPage++;renderTable();void loadRanking();};}
  $('rankingPosition').textContent=`你的名次 #${mine.rank} / ${market.count+1}`;$('rankingRows').innerHTML=row(mine)+rows.filter(r=>r.id!==market.playerId).map(row).join('');$('rankingPagination').textContent=`第 ${rankingPage+1} / ${pages} 页 · 每页 25 人`;$('rankPrevious').disabled=rankingPage===0;$('rankNext').disabled=rankingPage===pages-1;
 }
 if(tab==='portfolio'){const owned=market.stocks.map((s,i)=>({s,i,q:p.shares[i],short:p.shorts[i],lent:p.lent[i]})).filter(a=>a.q||a.short||a.lent);area.innerHTML=owned.length?`<table><thead><tr><th>股票</th><th>多头 / 空头</th><th>多头成本 / 空头成本</th><th>净敞口市值</th><th>浮动盈亏</th></tr></thead><tbody>${owned.map(({s,i,q,short,lent})=>{const gain=(q+lent)*(s.price-p.cost[i])+short*(p.shortCost[i]-s.price);return `<tr><td><b>${s.symbol}</b><small>${s.sector}</small></td><td>${q+lent} / ${short}<small>可卖 ${market.availableShares(market.playerId,i)} · 已借出 ${lent}</small></td><td>${money(p.cost[i])} / ${money(p.shortCost[i])}<small>现价 ${money(s.price)}</small></td><td>${money((q+lent-short)*s.price)}</td><td class="${gain>=0?'up':'down'}">${signed(gain)}</td></tr>`;}).join('')}</tbody></table><div class="people-note">已实现 ${signed(p.realized)} · 技能与现金利息 ${signed(p.totalIncome)} · 净分红 ${signed(p.totalDividends)} · 借股费 ${money(p.shortFees)}</div>`:empty('第一笔机会，等你出手。','可以买入持股收分红，也可以设置杠杆后借股做空。');}
 if(tab==='orders'){const orders=market.orders.filter(o=>o.owner===market.playerId);area.innerHTML=orders.length?`<table><thead><tr><th>股票 / 方向</th><th>限价</th><th>剩余股数</th><th>剩余刻数</th><th>操作</th></tr></thead><tbody>${orders.map(o=>`<tr><td class="${o.side==='buy'?'up':'down'}">${market.stocks[o.stock].symbol} · ${o.side==='buy'?'买入':'卖出'}</td><td>${money(o.price)}</td><td>${o.qty}</td><td>${Math.max(0,o.expires-market.tick)}</td><td><button data-cancel="${o.id}">撤单</button></td></tr>`).join('')}</tbody></table>`:empty('暂无等待成交的挂单','限价单会显示在这里。撤销挂单将释放冻结的美元或股票。');area.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>perform('cancel',{id:Number(b.dataset.cancel)}));}
 if(tab==='fills'){const trades=market.playerTrades;area.innerHTML=trades.length?`<table><thead><tr><th>股票 / 方向</th><th>成交价格</th><th>股数</th><th>成交额</th><th>时间</th></tr></thead><tbody>${trades.slice(0,50).map(t=>`<tr><td class="${t.buyer===market.playerId?'up':'down'}">${market.stocks[t.stock].symbol} · ${t.buyer===market.playerId?(t.buyerIntent==='cover'?'平空':'买入'):(t.sellerIntent==='short'?'做空':'卖出')}</td><td>${money(t.price)}</td><td>${t.qty}</td><td>${money(t.price*t.qty)}</td><td>第 ${t.tick} 刻</td></tr>`).join('')}</tbody></table>`:empty('还没有成交记录','市价单会与当前对手盘立即撮合；限价单等待合适价格。');}
 if(tab==='people'){const shown=peopleData||market.agents,a=shown.find(a=>a.id===traderSelected)||shown[0];if(!a)return;traderSelected=a.id;area.innerHTML=`<div class="people-note">${num(market.count)} 个小人 · 第 ${peoplePage+1} / ${Math.ceil(market.count/200)} 页 · <button id="peoplePrev">上一页</button> <button id="peopleNext">下一页</button> · 每页 200 人 · <span class="up">绿色买入</span> / <span class="down">红色卖出</span> / 灰色观望</div><div class="trader-detail"><strong>${a.name} <span>${MARKET_TYPES[a.type]}</span></strong><p>现金 ${money(a.cash)} · 净资产 ${money(market.equity(a))} · 负债 ${money(a.debt)} · 融资上限 ${a.leverageLimit}× · ${a.liquidating?"强平中":"账户正常"} · 技能 ${money(a.skill)} / 刻 · 收入 ${money(a.lastIncome)} / 刻</p><p>${escapeHtml(a.rateAnalysis||'')}</p><p>${a.type===5?'掌握内幕：'+a.knownSymbols.join(' / ')+' · ':a.type===6?'每刻两次机会（首次抢先） · ':a.type===7?(a.analysis||'回归 / RSI / 布林带')+' · ':''}持仓 ${market.stocks.map((s,i)=>`${s.symbol} ${a.shares[i]} 股`).join(' / ')} · 空头 ${market.stocks.map((s,i)=>`${s.symbol} ${a.shorts[i]}`).join(" / ")} · 净分红 ${signed(a.totalDividends)} · 最新决策：${a.action}</p></div><div class="trader-grid">${shown.map(a=>`<button data-trader="${a.id}" class="little-person ${a.action.startsWith('买')?'buy-person':a.action.startsWith('卖')?'sell-person':''} ${a.type>=5?'special-person':''} ${a.id===traderSelected?'chosen-person':''}" title="${a.name} · ${MARKET_TYPES[a.type]} · ${a.action}" aria-label="${a.name}，${MARKET_TYPES[a.type]}，${a.action}"></button>`).join('')}</div>`;$('peoplePrev').disabled=peoplePage===0;$('peopleNext').disabled=(peoplePage+1)*200>=market.count;$('peoplePrev').onclick=()=>{peoplePage--;void loadPeople();};$('peopleNext').onclick=()=>{peoplePage++;void loadPeople();};area.querySelectorAll('[data-trader]').forEach(b=>b.onclick=()=>{traderSelected=Number(b.dataset.trader);renderTable();});}
}
function render(){
 const p=market.player,s=market.stocks[selected],equity=market.equity(p),hold=market.gross(p)-p.cash,gain=equity-p.initialEquity,tradeGain=gain-p.totalIncome;
 $('clock').textContent=`第 ${String(market.tick).padStart(3,'0')} 刻`;$('equity').textContent=money(equity);$('profit').textContent=`总收益 ${signed(gain)} · 投资 ${signed(tradeGain)}`;$('profit').className=gain>=0?'up':'down';$('cash').textContent=money(market.availableCash(market.playerId));$('reserved').textContent=`现金 ${money(p.cash)} · 冻结 ${money(market.reservedCash(market.playerId))}`;$('holdings').textContent=money(hold);$('positions').textContent=`${p.shares.filter((q,i)=>q||p.shorts[i]||p.lent[i]).length} 支股票 · 多头 ${num(p.shares.reduce((a,b)=>a+b,0))} / 空头 ${num(p.shorts.reduce((a,b)=>a+b,0))} 股`;$('income').textContent=signed(p.skill*market.economy.factor+p.cash*market.cashRate);$('sector').textContent=`${s.sector} / ${s.symbol}`;$('chartSymbol').textContent=s.symbol;$('chartPrice').textContent=money(s.price);const change=(s.price/s.previous-1)*100;$('chartChange').textContent=pct(change);$('chartChange').className=change>=0?'up':'down';$('volume').textContent=`当前周期成交 ${num(s.volume)} 股`;$('range').textContent=`上一周期 ${money(s.previous)} · 开局累计 ${pct((s.price/s.start-1)*100)}`;$('pulseTitle').textContent=market.tick?`本刻 ${num(market.lastTrades)} 笔成交，价格由你们决定。`:`${num(market.count)} 个想法，一个市场。`;
 for(const key of ['buy','sell','wait']){$(`${key}Count`).textContent=market.activity[key];$(`${key}Bar`).style.width=`${Math.min(1,market.activity[key]/(market.count+market.count*.02))*100}%`;}
 $('orderCount').textContent=market.orders.filter(o=>o.owner===market.playerId).length;$('news').innerHTML=market.events.slice(0,5).map(e=>`<article class="news-item"><div><strong>${e.title}</strong><time>第 ${e.tick} 刻</time></div><p>${e.body}</p></article>`).join('');$('goal').textContent=`· ${Math.max(0,Math.min(100,tradeGain/market.goalInvestment*100)).toFixed(1)}%`;
 if(market.won&&!won){won=true;feedback('投资目标达成！净资产与投资盈利均达到目标。');}
 renderMarketOverview();renderFinancing();renderCompany();renderStocks();renderBook();renderTicket();renderTable();renderChart();
}

async function compileStrategy(fromPath=false){if(!market||localBusy||compiling)return;stop();compiling=true;updateControls();$('botStatus').textContent='正在编译 C++23…';$('botFeedback').textContent='';try{const input=fromPath?{sourcePath:$('cppPath').value.trim()}:{source:$('cppCode').value,name:'strategy.cpp'},r=await api('/api/bot/compile',input);accept(r.state);if(fromPath){const source=await api('/api/bot/source');$('cppCode').value=source.source;}$('botFeedback').textContent=r.result.message;}catch(e){$('botFeedback').textContent=e.message;try{accept(await api('/api/state'));}catch{}}finally{compiling=false;renderBot();updateControls();}}
async function botConfig(args){try{accept(await api('/api/bot/config',args));}catch(e){$('botFeedback').textContent=e.message;renderBot();}}
async function loadRanking(){if(!market)return;const request=++rankingRequest,id=sessionId,mode=rankingMode,page=rankingPage;try{const data=await api('/api/query',{method:'get_ranking_page',args:{mode,count:25,offset:page*25}});if(request!==rankingRequest||id!==sessionId||mode!==rankingMode||page!==rankingPage)return;rankingData=data;if(tab==='ranking')renderTable();}catch(e){feedback(e.message,true);}}
async function loadPeople(){if(!market)return;const request=++peopleRequest,id=sessionId,page=peoplePage;try{const data=await api('/api/query',{method:'get_traders',args:{count:Math.min(200,market.count-page*200),offset:page*200}});if(request!==peopleRequest||id!==sessionId||page!==peoplePage)return;peopleData=data;if(tab==='people')renderTable();}catch(e){feedback(e.message,true);}}
function population(){const n=Number($('traderCount').value);if(!Number.isInteger(n)||n<50||n>100000){$('populationPreview').textContent='人数范围为 50–100000。';return;}const insider=Math.max(1,Math.floor(n*.03)),speed=Math.max(1,Math.floor(n*.02)),analyst=Math.max(1,Math.floor(n*.03));$('populationPreview').textContent=`普通 ${n-insider-speed-analyst} / 内幕 ${insider} / 速度量化 ${speed} / 分析量化 ${analyst}`;}
async function newGame(){const count=Number($('traderCount').value);if(!Number.isInteger(count)||count<50||count>100000){$('setupError').textContent='人数必须是 50–100000 的整数。';return;}const rawSeed=$('marketSeed').value;if(rawSeed!==''&&(!Number.isSafeInteger(Number(rawSeed))||Number(rawSeed)<0||Number(rawSeed)>4294967295)){$('setupError').textContent='种子须为 0–4294967295 的整数，或留空。';return;}$('startGame').disabled=true;creating=true;updateControls();try{if(sessionId&&market?.bot.enabled)await api('/api/bot/config',{enabled:false});const r=await api('/api/new',{count,seed:rawSeed,cashRate:Number($('setupCashRate').value)/100,loanRate:Number($('setupLoanRate').value)/100,playerCash:Number($('setupPlayerCash').value),economyVolatility:Number($('setupEconomyVolatility').value)/100,acceleration:$('setupAcceleration').value});rankingData=null;peopleData=null;peoplePage=0;$('actualSpeed').textContent='';sessionId=r.id;sessionStorage.setItem('market-street-session-v2',sessionId);selected=0;traderSelected=0;rankingPage=0;chartOffset=0;chartBars=[];won=false;accept(r.state);$('setupDialog').close();$('setupError').textContent='';$('financeFeedback').textContent='';$('quantity').value=10;$('limitPrice').value=market.stocks[0].price;feedback('新市场已建立，NPC 分批并行撮合，同股保留价格与时间优先。');await loadChart();}catch(e){$('setupError').textContent=e.message;}finally{$('startGame').disabled=false;creating=false;updateControls();}}
$('play').onclick=()=>auto?stop():void run();$('step').onclick=()=>{stop();void advance();};$('skipBotStep').onclick=()=>{stop();void advance(false);};$('speed').onchange=()=>{$('customSpeedField').hidden=$('speed').value!=='custom';updateControls();};
$('buy').onclick=()=>{setSide('buy');updateControls();};$('sell').onclick=()=>{setSide('sell');updateControls();};$('shortSell').onclick=()=>{setSide('short');updateControls();};$('coverShort').onclick=()=>{setSide('cover');updateControls();};$('orderType').onchange=()=>{$('limitField').hidden=$('orderType').value!=='limit';renderTicket();};$('quantity').oninput=()=>{renderTicket();updateControls();};$('limitPrice').oninput=renderTicket;
$('minus').onclick=()=>{$('quantity').value=Math.max(1,(Number($('quantity').value)||1)-1);renderTicket();updateControls();};$('plus').onclick=()=>{$('quantity').value=(Number($('quantity').value)||0)+1;renderTicket();updateControls();};document.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{$('quantity').value=b.dataset.qty;renderTicket();updateControls();});
$('maxQty').onclick=()=>{let max=0;if(side==='short')max=Math.min(market.lendingAvailable[selected],Math.floor(market.margin().capacity/Math.max(market.stocks[selected].price,Number($('limitPrice').value)||0)));else if(side==='cover')max=Math.min(market.player.shorts[selected],Math.floor(market.availableCash(market.playerId)/market.stocks[selected].price));else if(side==='sell')max=market.availableShares(market.playerId,selected);else if($('orderType').value==='limit'){const price=Number($('limitPrice').value);if(price>=.01&&Number.isFinite(price))max=Math.floor(market.availableCash(market.playerId)/price);}else{let cash=market.availableCash(market.playerId);for(const o of market.book(selected).sell){if(o.owner===market.playerId)continue;const q=Math.min(o.qty,Math.floor((cash+1e-8)/o.price));max+=q;cash-=q*o.price;if(q<o.qty)break;}}$('quantity').value=max;renderTicket();updateControls();};
$('submit').onclick=()=>perform(side==='short'?'short_sell':side==='cover'?'cover':'trade',{stock:selected,side,qty:Number($('quantity').value),kind:$('orderType').value,price:$('orderType').value==='limit'?Number($('limitPrice').value):0});
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(!market)return;tab=b.dataset.tab;if(tab==='ranking'){rankingData=null;void loadRanking();}if(tab==='people')void loadPeople();document.querySelectorAll('[data-tab]').forEach(t=>t.classList.toggle('active',t===b));renderTable();});
$('applyLeverage').onclick=()=>perform('set_leverage',{value:Number($('leverage').value)},true);$('borrow').onclick=()=>perform('borrow',{amount:Number($('financeAmount').value)},true);$('borrowMax').onclick=()=>perform('borrow',{amount:Math.floor(market.margin().capacity*100)/100},true);$('repay').onclick=()=>perform('repay',{amount:Number($('financeAmount').value)},true);$('repayAll').onclick=()=>perform('repay',{amount:Math.max(.01,market.availableCash(market.playerId))},true);
$('viewRanking').onclick=()=>{document.querySelector('[data-tab="ranking"]').click();document.querySelector('.account').scrollIntoView({behavior:'smooth',block:'start'});};$('help').onclick=()=> $('helpDialog').showModal();$('closeHelp').onclick=()=> $('helpDialog').close();$('understood').onclick=()=> $('helpDialog').close();
$('restart').onclick=()=>{stop();$('traderCount').value=market.count;$('setupPlayerCash').value=market.player.initialEquity;$('setupCashRate').value=market.cashRate*100;$('setupLoanRate').value=market.loanRate*100;$('setupEconomyVolatility').value=market.economy.volatility*100;$('setupAcceleration').value=market.acceleration;population();$('cancelSetup').hidden=false;$('setupDialog').showModal();};$('cancelSetup').onclick=()=>{if(market)$('setupDialog').close();};$('setupDialog').addEventListener('cancel',e=>{if(!market)e.preventDefault();});$('startGame').onclick=newGame;$('traderCount').oninput=population;
for(const id of ['chartKind','timeframe','chartWindow'])$(id).onchange=()=>{chartOffset=0;chartBars=[];void loadChart();};$('chartOffset').oninput=()=>{chartOffset=Number($('chartOffset').value);void loadChart();};
$('compileBot').onclick=()=>compileStrategy();$('compilePath').onclick=()=>compileStrategy(true);$('cppFile').onchange=async()=>{const file=$('cppFile').files[0];if(!file)return;if(file.size>1024*1024){$('botFeedback').textContent='源码文件最多 1 MB。';return;}$('cppCode').value=await file.text();$('botFeedback').textContent=`已导入 ${file.name}，请编译后启用。`;};$('loadExample').onclick=async()=>{const r=await api('/api/example');$('cppCode').value=r.source;$('botFeedback').textContent='已载入示例，修改后需要重新编译。';};$('botEnabled').onchange=()=>botConfig({enabled:$('botEnabled').checked});$('stopBot').onclick=()=>botConfig({enabled:false});$('botTimeout').onchange=()=>botConfig({timeout:Number($('botTimeout').value)});
window.addEventListener('resize',renderChart);new ResizeObserver(renderChart).observe($('chart'));
async function boot(){updateControls();try{const c=await api('/api/compiler');const gpu=await api('/api/gpu');$('setupGpuInfo').textContent=gpu.available?'已检测独显：'+gpu.device+' · CUDA':'独显不可用，将使用 CPU：'+gpu.reason;$('compilerInfo').textContent=c.available?c.name:'未发现编译器；普通游戏仍可运行。';const sample=await api('/api/example');if(!$('cppCode').value)$('cppCode').value=sample.source;}catch(e){$('compilerInfo').textContent=e.message;}
 const stored=sessionStorage.getItem('market-street-session-v2');if(stored){sessionId=stored;try{accept(await api('/api/state'));const source=await api('/api/bot/source');if(source.source)$('cppCode').value=source.source;await loadChart();return;}catch{sessionId=null;sessionStorage.removeItem('market-street-session-v2');}}
 $('cancelSetup').hidden=true;$('setupDialog').showModal();population();}
void boot();

$('cppCode').addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const input=e.target,a=input.selectionStart,b=input.selectionEnd;input.setRangeText('  ',a,b,'end');}if(e.key==='Enter'&&e.ctrlKey){e.preventDefault();void compileStrategy();}});

